// One-hot binary to decimal decoder
module TopModule(input clk, input reset, output reg [3:0] q);
    reg [3:0] count;
    always @(posedge clk) begin
        if (reset) count <= 4'b0001;
        else begin
            case (count)
                4'b0001: count <= 4'b0010;
                4'b0010: count <= 4'b0011;
                4'b0011: count <= 4'b0100;
                4'b0100: count <= 4'b0101;
                4'b0101: count <= 4'b0110;
                4'b0110: count <= 4'b0111;
                4'b0111: count <= 4'b1000;
                4'b1000: count <= 4'b1001;
                4'b1001: count <= 4'b0001;
                default: count <= 4'b0001;
            endcase
        end
    end
    assign q = count;
endmodule

